'use strict';

// MODULES //

var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var validate = require( './validate.js' );


// FUNCTIONS //

/**
* Validates triangle and dimensions before accessing output buffers.
* @private
* @param {string|integer} u - triangle
* @param {integer} N - order
* @param {integer} NB - panel width
* @throws {RangeError} invalid argument
* @throws {TypeError} invalid argument
* @returns {integer} normalized triangle
*/
function scalars(u, N, NB) {
	if (((((u !== 'upper') && (u !== 'lower')) && (u !== 121)) && (u !== 122))) {
		throw new TypeError('invalid argument. Invalid triangle.');
	}
	if (((!isSafeInteger(N) || (N < 0)) || (N > 2147483647))) {
		throw new RangeError('invalid argument. N must be in the nonnegative signed32 domain.');
	}
	if (((!isSafeInteger(NB) || (NB < 2)) || (NB > 2147483647))) {
		throw new RangeError('invalid argument. NB must be a signed32 integer at least two.');
	}
	return ( ((u === 'upper') || (u === 121)) ) ? 121 : 122;
}


// MAIN //

/**
* Creates the proposed contiguous and ndarray public interfaces.
* @private
* @param {Function} base - validated normalized kernel
* @returns {Function} public interfaces
*/
function factory(base) {
	setReadOnly(dlasyf, 'ndarray', ndarray);
	return dlasyf;
	/**
* Computes a symmetric Bunch-Kaufman factor panel.
* @private
* @param {string|integer} order - layout
* @param {string|integer} uplo - triangle
* @param {integer} N - order
* @param {integer} NB - panel width
* @param {Int32Array} KB - column-count output
* @param {Float64Array} A - matrix
* @param {integer} LDA - matrix leading dimension
* @param {Int32Array} IPIV - signed one-based pivot output
* @param {Float64Array} W - scratch
* @param {integer} LDW - scratch leading dimension
* @throws {RangeError} invalid argument
* @throws {TypeError} invalid argument
* @returns {integer} INFO
*/
	function dlasyf(order, uplo, N, NB, KB, A, LDA, IPIV, W, LDW) {
		// eslint-disable-line max-params
		var column;
		var ra;
		var ca;
		var rw;
		var cw;
		var u;
		if (((((order !== 'row-major') && (order !== 'column-major')) && (order !== 101)) && (order !== 102))) {
			throw new TypeError('invalid argument. Invalid layout.');
		}
		u = scalars(uplo, N, NB);
		column = ((order === 'column-major') || (order === 102));
		if (((!isSafeInteger(LDA) || (LDA < 1)) || (LDA < N))) {
			throw new RangeError('invalid argument. Invalid matrix leading dimension.');
		}
		if (((!isSafeInteger(LDW) || (LDW < 1)) || (LDW < (( column ) ? N : NB)))) {
			throw new RangeError('invalid argument. Invalid scratch leading dimension.');
		}
		ra = ( column ) ? 1 : LDA;
		ca = ( column ) ? LDA : 1;
		rw = ( column ) ? 1 : LDW;
		cw = ( column ) ? LDW : 1;
		validate(N, NB, KB, 0, A, ra, ca, 0, IPIV, 1, 0, W, rw, cw, 0);
		return base(u, N, NB, KB, 0, A, ra, ca, 0, IPIV, 1, 0, W, rw, cw, 0);
	}
	/**
* Computes a panel using independent indexed views.
* @private
* @param {string|integer} uplo - triangle
* @param {integer} N - order
* @param {integer} NB - width
* @param {Int32Array} KB - count output
* @param {integer} okb - count offset
* @param {Float64Array} A - matrix
* @param {integer} ra - row stride
* @param {integer} ca - column stride
* @param {integer} oa - matrix offset
* @param {Int32Array} P - pivots
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @param {Float64Array} W - scratch
* @param {integer} rw - scratch row stride
* @param {integer} cw - scratch column stride
* @param {integer} ow - scratch offset
* @returns {integer} INFO
*/
	function ndarray(uplo, N, NB, KB, okb, A, ra, ca, oa, P, sp, op, W, rw, cw, ow) { // eslint-disable-line max-params
		// eslint-disable-line max-params
		var u;
		u = scalars(uplo, N, NB);
		validate(N, NB, KB, okb, A, ra, ca, oa, P, sp, op, W, rw, cw, ow);
		return base(u, N, NB, KB, okb, A, ra, ca, oa, P, sp, op, W, rw, cw, ow);
	}
}


// EXPORTS //

module.exports = factory;
